let S=await load(),page="desk",opened=null,query="",filter="all",reportPreview=false;let audioPlayer=null,activePodcast=null,playerVisible=true;S=S&&typeof S==="object"?S:{};S.cases=Array.isArray(S.cases)?S.cases:[];S.library=Array.isArray(S.library)?S.library:[];S.podcasts=Array.isArray(S.podcasts)?S.podcasts:[];S.settings={theme:"dark",accent:"gold",notify:true,reminderMinutes:60,reminderTime:"09:00",density:"comfortable",font:"vazirmatn",iconColor:"black",...(S.settings&&typeof S.settings==="object"?S.settings:{})};S.cases=S.cases.filter(c=>c&&typeof c==="object").map(c=>({...c,steps:Array.isArray(c.steps)?c.steps:[]}));S.cases.forEach(c=>{if(!c.steps.some(x=>x.isFinalResult)){c.steps.push({id:crypto.randomUUID(),title:"نتیجه نهایی",order:c.steps.length+1,status:"pending",startDate:"",dueDate:"",note:"",completedAt:"",attachments:[],isFinalResult:true})}});const $=s=>document.querySelector(s),all=()=>S.cases.flatMap(c=>c.steps.map(x=>({...x,caseName:c.title,clientName:c.client||"موکل ثبت نشده",caseId:c.id}))),esc=x=>String(x||"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-")},date=x=>x?new Date(x+"T00:00:00").toLocaleDateString("fa-IR"):"—",pct=c=>Math.round(c.steps.filter(x=>x.status==="done").length/Math.max(c.steps.length,1)*100),current=c=>c.steps.find(x=>x.status!=="done");
async function persist(){await save(S);await scheduleCaseReminders(S.cases,S.settings);render()}function theme(){const t=S.settings.theme==="system"?(matchMedia("(prefers-color-scheme:light)").matches?"light":"dark"):S.settings.theme;document.documentElement.dataset.theme=t;document.documentElement.dataset.accent=S.settings.accent;document.documentElement.dataset.density=S.settings.density||"comfortable";document.documentElement.dataset.font=S.settings.font||"vazirmatn";if(S.settings.customAccent)document.documentElement.style.setProperty("--accent",S.settings.customAccent);if(S.settings.iconColor&&S.settings.iconColor!=="black")document.documentElement.style.setProperty("--app-icon-color",S.settings.iconColor)}
function icon(n){const p={folder:'<path d="M3 7h7l2 2h9v10H3z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',home:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="5" rx="2"/><rect x="13" y="10" width="8" height="11" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/>',archive:'<path d="M3 4h18v4H3zM5 8v12h14V8m-9 4h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4m8-4v4M3 10h18"/>',book:'<path d="M4 4h16v17H7a3 3 0 0 1-3-3zM4 18a3 3 0 0 1 3-3h13"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19 13a7 7 0 0 0 0-2l2-1-2-4-2 1a7 7 0 0 0-2-1l-.3-2h-5L9 6a7 7 0 0 0-2 1L5 6l-2 4 2 1a7 7 0 0 0 0 2l-2 1 2 4 2-1a7 7 0 0 0 2 1l.3 2h5l.7-2a7 7 0 0 0 2-1l2 1 2-4z"/>',check:'<path d="m5 12 4 4L19 6"/>',edit:'<path d="m4 16-1 5 5-1L20 8l-4-4z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 20h16"/>',trash:'<path d="M4 6h16M9 6V4h6v2m3 0-1 15H7L6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',scale:'<path d="m12 3 9 4-9 4-9-4 9-4zm0 8v10m-7 0h14M5 7l-3 8h6z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20a6 6 0 0 1 12 0m1-14a3 3 0 0 1 0 6m2 2a5 5 0 0 1 3 6"/>',file:'<path d="M14 2H6v20h12V8zM14 2v6h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',audio:'<path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+(p[n]||p.file)+'</svg>'}
const nav=[["desk","home","میزکار"],["archive","archive","آرشیو"],["calendar","calendar","تقویم"],["library","book","کتابخانه"],["settings","settings","تنظیمات"]];
function routeState(){return {__pooshe:true,page,openedId:opened?.id||null,reportPreview}}
function pushRoute(){if(!history.state?.__pooshe)history.replaceState(routeState(),"");history.pushState(routeState(),"")}
function goPage(next){if(page===next&&!opened)return;pushRoute();page=next;opened=null;render()}
function openCase(id){const c=S.cases.find(x=>x.id===id);if(!c)return;pushRoute();opened=c;render()}
window.addEventListener("popstate",e=>{reportPreview=false;if(e.state?.__pooshe){page=e.state.page||"desk";opened=S.cases.find(c=>c.id===e.state.openedId)||null;render()}else{opened=null;page="desk";history.replaceState(routeState(),"");render()}});if(Capacitor.isNativePlatform()){App.addListener("backButton",()=>{if(reportPreview||opened||page!=="desk"){history.back();return}App.exitApp()})}
function getAudio(){if(!audioPlayer){audioPlayer=document.createElement("audio");audioPlayer.preload="metadata";audioPlayer.addEventListener("play",updatePlayer);audioPlayer.addEventListener("pause",updatePlayer);audioPlayer.addEventListener("ended",()=>{updatePlayer();changePodcast(1)});document.body.appendChild(audioPlayer)}return audioPlayer}
function playerPanel(){return '<div class="persistent-player '+(playerVisible?"":"player-hidden")+'"><b class="player-title">'+esc(activePodcast?.title||"")+'</b><button id="playerPrev" title="پادکست قبلی" aria-label="پادکست قبلی">⏮</button><button id="playerPlay" title="پخش / مکث">▶</button><button id="playerNext" title="پادکست بعدی" aria-label="پادکست بعدی">⏭</button></div>'}
function updatePlayer(){const a=getAudio(),playing=activePodcast?.id,b=$("#playerPlay");if(b)b.textContent=a.paused?"▶":"Ⅱ";const i=S.podcasts.findIndex(p=>p.id===playing),prev=$("#playerPrev"),next=$("#playerNext");if(prev)prev.disabled=i<=0;if(next)next.disabled=i<0||i>=S.podcasts.length-1;document.querySelectorAll("[data-podcast-toggle]").forEach(x=>{x.textContent=x.dataset.podcastToggle===playing&&!a.paused?"Ⅱ":"▶";x.setAttribute("aria-label",x.dataset.podcastToggle===playing&&!a.paused?"مکث":"پخش")});document.querySelectorAll("[data-podcast-prev]").forEach(x=>x.disabled=i<=0);document.querySelectorAll("[data-podcast-next]").forEach(x=>x.disabled=i<0||i>=S.podcasts.length-1)}
function rememberPodcastPosition(){const a=getAudio();if(!activePodcast||!Number.isFinite(a.currentTime))return;S.settings.lastPodcastId=activePodcast.id;S.settings.lastPodcastTime=a.currentTime;save(S)}
function restoreLastPodcast(){if(activePodcast&&getAudio().src)return;const p=S.podcasts.find(x=>x.id===S.settings.lastPodcastId);if(!p)return;activePodcast=p;const src=p.dataUrl||p.url||"";if(!src)return;const a=getAudio();a.src=src;a.addEventListener("loadedmetadata",()=>{const t=Number(S.settings.lastPodcastTime)||0;if(t>0&&Number.isFinite(a.duration))a.currentTime=Math.min(t,Math.max(0,a.duration-0.5));updatePlayer()},{once:true});a.load();const title=$(".player-title");if(title)title.textContent=p.title}
function playPodcast(p){const a=getAudio(),src=p.dataUrl||p.url||"";if(!src)return;const same=activePodcast?.id===p.id&&a.src===src;if(same&&!a.paused){a.pause();updatePlayer();return}if(!same){activePodcast=p;a.src=src;a.load();S.settings.lastPodcastId=p.id;S.settings.lastPodcastTime=0;save(S);render()}activePodcast=p;a.play().catch(()=>toast("پخش فایل صوتی ممکن نشد"));const t=$(".player-title");if(t)t.textContent=p.title;playerVisible=true;$(".persistent-player")?.classList.remove("player-hidden");updatePlayer()}
function changePodcast(delta){const list=S.podcasts||[],i=list.findIndex(p=>p.id===(activePodcast?.id||S.settings.lastPodcastId)),target=i<0?(delta>0?0:list.length-1):i+delta;if(target<0||target>=list.length)return;playPodcast(list[target])}
function bindPlayer(){const a=getAudio();restoreLastPodcast();if(!a.dataset.positionTracking){a.dataset.positionTracking="1";let lastSaved=0;a.addEventListener("timeupdate",()=>{if(!a.paused&&a.currentTime-lastSaved>=5){lastSaved=a.currentTime;rememberPodcastPosition()}});a.addEventListener("pause",rememberPodcastPosition)}$("#playerPlay")?.addEventListener("click",()=>{if(!a.src){const p=S.podcasts.find(x=>x.id===S.settings.lastPodcastId)||S.podcasts.at(-1);if(p)playPodcast(p);return}if(a.paused)a.play().catch(()=>toast("پخش فایل صوتی ممکن نشد"));else a.pause();updatePlayer()});$("#playerPrev")?.addEventListener("click",()=>changePodcast(-1));$("#playerNext")?.addEventListener("click",()=>changePodcast(1));document.querySelectorAll("[data-podcast-toggle]").forEach(b=>b.addEventListener("click",()=>{const p=S.podcasts.find(x=>x.id===b.dataset.podcastToggle);if(p)playPodcast(p)}));document.querySelectorAll("[data-podcast-prev]").forEach(b=>b.addEventListener("click",()=>changePodcast(-1)));document.querySelectorAll("[data-podcast-next]").forEach(b=>b.addEventListener("click",()=>changePodcast(1)));updatePlayer()}

function shell(html){$("#app").innerHTML='<div class="shell"><header><div class="brand"><span>'+icon("folder")+'</span><div><b class="brand-name">پوشه<sup class="app-version">1.0.0</sup></b><small>دستیار وکلاء</small></div></div><div class="head-actions">'+(page!=="library"?playerPanel():"")+(page!=="library"?'<button id="playerToggle" class="player-toggle" title="نمایش / پنهان کردن پخش‌کننده">♫</button>':"")+'</div></header><main>'+html+'</main><nav>'+nav.map(n=>'<button data-page="'+n[0]+'" class="'+(page===n[0]?"active":"")+'">'+icon(n[1])+'<small>'+n[2]+'</small></button>').join("")+'</nav><div id="modal"></div><div id="toast"></div></div>';const audio=getAudio();if(page==="library"){audio.controls=true;audio.classList.add("podcast-audio-controls");const id=activePodcast?.id||S.settings.lastPodcastId;const slot=id?$("#podcastAudioSlot-"+id):null;if(slot)slot.appendChild(audio);else document.body.appendChild(audio)}else{audio.controls=false;audio.classList.remove("podcast-audio-controls");document.body.appendChild(audio)}document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>goPage(b.dataset.page));$("#playerToggle")?.addEventListener("click",()=>{playerVisible=!playerVisible;$(".persistent-player")?.classList.toggle("player-hidden",!playerVisible)});bindPlayer();}
function head(t,d,button){const titled=["میزکار","آرشیو پرونده‌ها","تقویم پیگیری"].includes(t);const label=t==="میزکار"?"میز کار":t;return '<div class="pagehead"><div class="'+(t==="میزکار"?"desk-heading":"")+'">'+(titled?'<div class="layer-title-group"><h1>'+label+'</h1><span class="desk-separator">|</span><small>وکیل- خانم سمیه رحیمی فرد</small></div>':'<h1>'+label+'</h1>')+'<p>'+d+'</p></div>'+(button||"")+'</div>'}
function card(c){const s=current(c);return '<article class="case" data-open="'+c.id+'"><div class="row"><span class="folder">'+icon("folder")+'</span><label>'+c.group+' · '+c.type+'</label><button class="case-delete" data-deletecase="'+c.id+'" title="حذف پرونده" aria-label="حذف پرونده">'+icon("trash")+'</button></div><h3>'+esc(c.title)+'</h3><p>'+icon("users")+' '+esc(c.client||"موکل ثبت نشده")+(c.phone1?' · <a class="client-phone" href="tel:'+esc(c.phone1)+'">'+esc(c.phone1)+'</a>':"")+(c.phone2?' · <a class="client-phone" href="tel:'+esc(c.phone2)+'">'+esc(c.phone2)+'</a>':"")+'　 ·　 '+esc(c.fileNo||"بدون شماره")+'</p><div class="bar"><i style="width:'+pct(c)+'%"></i></div><div class="foot"><span>'+pct(c)+'٪ تکمیل</span><span>'+(s?"گام جاری: "+esc(s.title):"مختومه")+'</span></div></article>'}
async function downloadFile(name,content,mime){const blob=new Blob([content],{type:mime});if(Capacitor.isNativePlatform()){try{const path="Download/Pooshe/"+name;await Filesystem.writeFile({path,data:content,directory:Directory.ExternalStorage,encoding:Encoding.UTF8,recursive:true});toast("فایل Excel در حافظه داخلی، پوشه Download/Pooshe ذخیره شد");return}catch(e){console.error("Downloads export failed",e);try{const path="Pooshe/"+name;const saved=await Filesystem.writeFile({path,data:content,directory:Directory.Documents,encoding:Encoding.UTF8,recursive:true});const uri=saved.uri||(await Filesystem.getUri({path,directory:Directory.Documents})).uri;await Share.share({title:name,text:"ذخیره فایل در Downloads ممکن نبود؛ فایل جایگزین در Documents/Pooshe ذخیره شد",url:uri,dialogTitle:"ذخیره یا اشتراک فایل Excel"});toast("دسترسی به Downloads ممکن نبود؛ فایل در Documents/Pooshe ذخیره شد");return}catch(f){alert("ذخیره فایل ناموفق بود: "+(f.message||f));return}}}if(typeof File!=="undefined"&&navigator.share&&navigator.canShare){try{const file=new File([blob],name,{type:mime});if(navigator.canShare({files:[file]})){await navigator.share({files:[file],title:name});return}}catch(e){if(e.name==="AbortError")return;console.warn("Share export fallback",e)}}const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.rel="noopener";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast("دانلود فایل آغاز شد")}
function exportSheet(title,headers,rows){title="وکیل- خانم سمیه رحیمی فرد | "+title;const cell=v=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");const html='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:Tahoma}table{border-collapse:collapse}td,th{border:1px solid #999;padding:7px;text-align:right;mso-number-format:"\\@";}</style></head><body><table><thead><tr><th colspan="'+headers.length+'">'+cell(title)+'</th></tr><tr>'+headers.map(x=>'<th>'+cell(x)+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+cell(x)+'</td>').join("")+'</tr>').join("")+'</tbody></table></body></html>';downloadFile("pooshe-report.xls","\ufeff"+html,"application/vnd.ms-excel;charset=utf-8")}


function printReport(title,headers,rows){
 title="وکیل- خانم سمیه رحیمی فرد | "+title;
 const cell=v=>String(v??"—").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
 const html='<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>'+cell(title)+'</title><style>body{font-family:Tahoma,sans-serif;color:#111;background:#fff;margin:24px}h2{font-size:19px;margin:0 0 14px}p{font-size:12px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #aeb7c2;padding:8px;text-align:right;font-size:11px;vertical-align:top}th{background:#e8edf3;font-weight:800}.report-actions{display:flex;gap:8px;margin:16px 0}.report-actions button{padding:10px 18px;border:0;border-radius:8px;background:#183c48;color:white;font-weight:700}@media print{.report-actions{display:none}body{margin:0}@page{margin:16mm}}</style></head><body><div class="report-actions"><button onclick="window.print()">چاپ / ذخیره PDF</button><button onclick="history.back()">بازگشت به برنامه</button></div><h2>'+cell(title)+'</h2><p>تاریخ تهیه: '+new Date().toLocaleDateString("fa-IR")+'</p><table><thead><tr>'+headers.map(x=>'<th>'+cell(x)+'</th>').join("")+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+cell(x)+'</td>').join("")+'</tr>').join("")+'</tbody></table></body></html>';
 reportPreview=true;history.pushState({...routeState(),reportPreview:true},"");
 const modalRoot=$("#modal");if(!modalRoot)return;
 modalRoot.innerHTML='<div class="report-preview-backdrop"><section class="report-preview" role="dialog" aria-label="پیش‌نمایش گزارش PDF"><div class="report-preview-toolbar"><b>پیش‌نمایش PDF</b><div><button type="button" id="printReportNow">چاپ / ذخیره PDF</button><button type="button" id="closeReportPreview">بازگشت</button></div></div><iframe title="پیش‌نمایش گزارش PDF"></iframe></section></div>';
 const frame=modalRoot.querySelector("iframe"),doc=frame.contentDocument;doc.open();doc.write(html);doc.close();
 $("#printReportNow").onclick=()=>{try{frame.contentWindow.focus();frame.contentWindow.print()}catch(e){alert("چاپ در این دستگاه در دسترس نیست: "+e.message)}};
 $("#closeReportPreview").onclick=()=>{if(history.state?.reportPreview)history.back();else{reportPreview=false;modalRoot.innerHTML=""}};
}


function reportButtons(){return '<div class="export-actions"><button class="outline" id="xlsExport">Excel</button><button class="outline" id="pdfExport">PDF</button></div>'}
function reportRows(){return S.cases.map(c=>[c.title,c.group,c.type,c.client,c.fileNo,c.closed?"مختومه":"در جریان",pct(c)+"٪",c.steps.length,c.steps.filter(s=>s.status==="done").length])}
function calendarRows(){return all().flatMap(s=>[{when:s.startDate,kind:"شروع مرحله",title:s.title,caseName:s.caseName,status:s.status},{when:s.dueDate,kind:"پایان مرحله",title:s.title,caseName:s.caseName,status:s.status},...(s.eventDate?[{when:s.eventDate,kind:"قرار / رویداد",title:s.eventTitle||s.title,caseName:s.caseName,status:s.status}]:[])]).filter(x=>x.when).sort((a,b)=>a.when.localeCompare(b.when)).map(x=>[date(x.when),x.kind,x.caseName,x.title,x.status==="done"?"انجام‌شده":"در انتظار"])}
function bindExports(){const stats=page==="stats",headers=page==="calendar"?["تاریخ","نوع رویداد","پرونده","گام","وضعیت"]:stats?["شاخص آماری","تعداد"]:["عنوان پرونده","گروه","نوع","موکل","شماره پرونده","وضعیت","پیشرفت","تعداد گام","گام تکمیل‌شده"],rows=page==="calendar"?calendarRows():stats?(()=>{const a=S.cases,total=a.length,legal=a.filter(c=>c.group==="حقوقی").length,criminal=a.filter(c=>c.group==="کیفری").length,open=a.filter(c=>!c.closed).length,closed=a.filter(c=>c.closed).length,success=a.filter(c=>c.outcome==="success").length,fail=a.filter(c=>c.outcome==="fail").length;return [["کل پرونده‌ها",total],["حقوقی",legal],["کیفری",criminal],["سایر / ثبت‌نشده",Math.max(0,total-legal-criminal)],["جاری",open],["مختومه",closed],["نتیجه موفق",success],["نتیجه ناموفق",fail],["نتیجه تعیین‌نشده",total-success-fail]]})():reportRows(),title=page==="calendar"?"گزارش تقویم پیگیری":stats?"گزارش ارزیابی آماری پرونده‌ها":"گزارش میزکار و پرونده‌ها";$("#pdfExport")?.addEventListener("click",()=>printReport(title,headers,rows));$("#xlsExport")?.addEventListener("click",()=>exportSheet(title,headers,rows))}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
async function addStepFiles(c,s,files){for(const file of files){if(file.size>12*1024*1024){alert("حداکثر حجم هر فایل ۱۲ مگابایت است: "+file.name);continue}const data=await fileData(file);s.attachments=s.attachments||[];s.attachments.push({id:crypto.randomUUID(),name:file.name,type:file.type||"application/octet-stream",size:file.size,addedAt:new Date().toISOString(),data})}await persist()}
function openAttachment(a){const preview=/^(application\/pdf|image\/|text\/)/i.test(a.type||"");if(!preview){const link=document.createElement("a");link.href=a.data;link.download=a.name;document.body.appendChild(link);link.click();link.remove();return}const modal=$("#modal");if(!modal)return;modal.innerHTML='<div class="shade"><section class="file-viewer"><div class="row"><b>'+esc(a.name)+'</b><button class="outline" id="closeFile">بستن</button></div><iframe title="'+esc(a.name)+'" src="'+a.data+'"></iframe><a class="outline" download="'+esc(a.name)+'" href="'+a.data+'">دانلود فایل</a></section></div>';$("#closeFile").onclick=()=>modal.innerHTML="";}
function desk(){const open=S.cases.filter(c=>!c.closed),late=all().filter(s=>s.dueDate&&s.dueDate<=today()&&s.status!=="done");return head("میزکار","",'<div class="head-tools desk-tools"><button class="primary" id="new">＋ ثبت پرونده</button>'+reportButtons()+'</div>')+'<div class="stats"><div><small>پرونده‌های جاری</small><b>'+open.length+'</b></div><div><small>موعدهای سررسید</small><b>'+late.length+'</b></div><div><small>پرونده‌های مختومه</small><b>'+S.cases.filter(c=>c.closed).length+'</b></div><div><small>گام‌های امروز</small><b>'+all().filter(s=>s.dueDate===today()&&s.status!=="done").length+'</b></div></div><div class="section"><div><h2>پرونده‌های در جریان</h2><small>برای مشاهده مراحل، پوشه را باز کنید.</small></div></div>'+(open.length?'<div class="cards">'+open.slice(0,8).map(card).join("")+'</div>':'<div class="empty"><h3>هنوز پرونده‌ای ثبت نشده است</h3><p>با ثبت اولین پرونده، مسیر انجام کار اینجا نمایش داده می‌شود.</p><button class="primary" id="newEmpty">＋ ثبت اولین پرونده</button></div>')+'<div class="section"><div><h2>اقدامات نزدیک</h2><small>موعدهای ثبت‌شده</small></div></div><div class="list">'+all().filter(s=>s.status!=="done"&&s.dueDate).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,5).map(s=>'<div><b>'+esc(s.title)+'</b><small>'+esc(s.caseName)+' · '+date(s.dueDate)+'</small></div>').join("")+'</div>'}
function archive(){const a=S.cases.filter(c=>(filter==="all"||filter==="open"&&!c.closed||filter==="closed"&&c.closed)&&(!query||[c.title,c.client,c.fileNo,c.type].join(" ").includes(query)));return head("آرشیو پرونده‌ها","جستجو و دسترسی به سوابق پرونده‌ها",'<div class="head-tools archive-tools"><button class="primary" id="new">＋ ثبت پرونده</button>'+reportButtons()+'<button class="outline" id="statsOpen">ارزیابی آماری</button></div>')+'<div class="toolbar"><input id="q" placeholder="جستجوی عنوان، موکل یا شماره..." value="'+esc(query)+'"><select id="filter"><option value="all">همه پرونده‌ها</option><option value="open">در جریان</option><option value="closed">مختومه</option></select></div>'+(a.length?'<div class="cards">'+a.map(card).join("")+'</div>':'<div class="empty">پرونده‌ای پیدا نشد.</div>')}
function barChart(title,items){const max=Math.max(1,...items.map(x=>x.value));return '<section class="stat-chart"><h3>'+title+'</h3><div class="stat-bars">'+items.map(x=>'<div class="stat-bar-row"><span>'+x.label+'</span><div class="stat-bar-track"><i style="width:'+Math.round(x.value/max*100)+'%"></i></div><b>'+x.value+'</b></div>').join("")+'</div></section>'}
function statsPage(){const a=S.cases,total=a.length,legal=a.filter(c=>c.group==="حقوقی").length,criminal=a.filter(c=>c.group==="کیفری").length,open=a.filter(c=>!c.closed).length,closed=a.filter(c=>c.closed).length,success=a.filter(c=>c.outcome==="success").length,fail=a.filter(c=>c.outcome==="fail").length,unknown=total-success-fail;return head("ارزیابی آماری","نمایش آماری پرونده‌های ثبت‌شده در آرشیو",'<div class="head-tools">'+reportButtons()+'<button class="outline" id="backArchive">بازگشت به آرشیو</button></div>')+'<div class="stats"><div><small>کل پرونده‌ها</small><b>'+total+'</b></div><div><small>حقوقی</small><b>'+legal+'</b></div><div><small>کیفری</small><b>'+criminal+'</b></div><div><small>مختومه</small><b>'+closed+'</b></div></div><div class="stats-charts">'+barChart("پرونده‌های حقوقی و کیفری",[{label:"حقوقی",value:legal},{label:"کیفری",value:criminal},{label:"سایر / ثبت‌نشده",value:Math.max(0,total-legal-criminal)}])+barChart("وضعیت پرونده‌ها",[{label:"جاری",value:open},{label:"مختومه",value:closed}])+barChart("نتیجه پرونده‌ها",[{label:"موفق",value:success},{label:"ناموفق",value:fail},{label:"تعیین‌نشده",value:unknown}])+'</div><p class="hint">نتیجه موفق یا ناموفق فقط برای پرونده‌هایی محاسبه می‌شود که نتیجه آن‌ها در فرم پرونده تعیین شده باشد.</p>'}
function calendar(){const a=[];for(const s of all()){if(s.startDate)a.push({date:s.startDate,title:"شروع مرحله: "+s.title,caseName:s.caseName,clientName:s.clientName,status:s.status});if(s.dueDate)a.push({date:s.dueDate,title:"پایان مرحله: "+s.title,caseName:s.caseName,clientName:s.clientName,status:s.status});if(s.eventDate)a.push({date:s.eventDate,title:"قرار: "+(s.eventTitle||s.title),caseName:s.caseName,clientName:s.clientName,status:s.status,isReminder:true,stepId:s.id,caseId:s.caseId,enabled:s.eventReminderEnabled!==false})}a.sort((x,y)=>x.date.localeCompare(y.date));return head("تقویم پیگیری","رویدادهای شروع و پایان مراحل و قرارهای پرونده‌ها.",'<div class="head-tools calendar-tools"><button class="primary" id="new">＋ ثبت پرونده</button>'+reportButtons()+'</div>')+'<div class="list calendar-reminders">'+(a.length?a.map(s=>'<div class="calendar-item"><div class="calendar-item-info"><b>'+esc(s.title)+'</b><small>'+esc(s.caseName)+(s.isReminder?' · موکل: '+esc(s.clientName):"")+' · '+date(s.date)+' · '+(s.status==="done"?"انجام‌شده":"در انتظار")+(s.isReminder?(s.enabled?' · یادآور فعال':' · یادآور غیرفعال'):"")+'</small></div>'+(s.isReminder?'<div class="calendar-reminder-actions"><button class="outline" data-reminder-toggle="'+s.stepId+'">'+(s.enabled?"غیرفعال‌کردن یادآور":"فعال‌کردن یادآور")+'</button><button class="link" data-reminder-delete="'+s.stepId+'">حذف</button></div>':"")+'</div>').join(""):'<div>برای مراحل، تاریخ شروع، پایان یا قرار تعیین کنید تا رویدادها اینجا ظاهر شوند.</div>')+'</div><p class="hint">اعلان وب هنگام فعال بودن برنامه قابل نمایش است؛ اعلان زمان‌بندی‌شده در Android از قابلیت اعلان محلی استفاده می‌کند.</p>'}
const BOOKS=["قوانین و مقررات","رویه قضایی","فرم‌ها و نمونه متون","چک‌لیست‌های تخصصی"];
function library(){const entries=S.library||[],pods=S.podcasts||[];const playing=activePodcast||pods.find(p=>p.id===S.settings.lastPodcastId)||null;return head("کتابخانه حقوقی","مرجع شخصی منابع، فرم‌ها، دانش و پادکست‌های دفتر.")+'<div class="cards">'+BOOKS.map((x,i)=>'<article class="book"><span>'+icon("book")+'</span><h3>'+x+'</h3><p>'+entries.filter(e=>e.kind===i).length+' منبع ثبت‌شده</p><button class="outline" data-book="'+i+'">مشاهده / افزودن محتوا</button></article>').join("")+'</div><section class="podcast-section namello-podcast"><div class="podcast-head"><div><span class="podcast-icon">'+icon("audio")+'</span><div><h2>پادکست صوتی حقوقی</h2><p>پخش مستقیم فایل‌های صوتی از حافظه دستگاه</p></div></div><button class="primary" id="addPodcast">＋ افزودن پادکست</button></div>'+(pods.length?'<div class="podcast-list">'+pods.map((p,i)=>'<article class="podcast-card" data-podcast-card="'+p.id+'"><div class="podcast-card-head"><span class="podcast-play podcast-number">'+String(i+1).padStart(2,"0")+'</span><div><b>'+esc(p.title||p.fileName||"پادکست حقوقی")+'</b><small>'+esc(p.fileName||"فایل صوتی")+(p.duration?" · "+esc(p.duration):"")+'</small></div><button class="link" data-delpodcast="'+p.id+'">حذف</button></div><div class="podcast-card-player" id="podcastAudioSlot-'+p.id+'">'+(playing?.id===p.id?'':'<button class="outline podcast-select" data-podcast-toggle="'+p.id+'">▶ پخش این فایل</button>')+'</div><div class="podcast-track-controls"><button class="outline" data-podcast-prev="'+p.id+'" '+(i===0?"disabled":"")+' aria-label="Previous">⏮</button><button class="primary" data-podcast-toggle="'+p.id+'">'+(playing?.id===p.id&&!getAudio().paused?"Ⅱ":"▶")+'</button><button class="outline" data-podcast-next="'+p.id+'" '+(i===pods.length-1?"disabled":"")+' aria-label="Next">⏭</button></div></article>').join("")+'</div>':'<div class="podcast-empty">هنوز فایل صوتی اضافه نشده است. با زدن «افزودن پادکست» فایل را از پوشه دانلودها انتخاب کنید.</div>')+'</section>'+(entries.length?'<div class="section"><h2>منابع ثبت‌شده</h2></div><div class="list">'+entries.map(e=>'<div><b>'+esc(e.title)+'</b><small>'+BOOKS[e.kind]+(e.note?" · "+esc(e.note):"")+'</small>'+(e.url&&/^https?:\/\//i.test(e.url)?'<a href="'+esc(e.url)+'" target="_blank" rel="noopener noreferrer">بازکردن منبع ↗</a>':"")+'<button class="link" data-delbook="'+e.id+'">حذف</button></div>').join("")+'</div>':'')+'<div class="section"><h2>منابع رسمی پیشنهادی</h2></div><div class="list"><a href="https://qavanin.ir" target="_blank" rel="noopener noreferrer">سامانه ملی قوانین و مقررات ↗</a><a href="https://www.dadiran.ir" target="_blank" rel="noopener noreferrer">درگاه خدمات الکترونیک قضایی ↗</a></div><p class="hint">اعتبار و آخرین اصلاحات قوانین را از مرجع رسمی کنترل کنید.</p>'}

function settings(){const s=S.settings;const folder=s.backupFolderName||"پوشه‌ای انتخاب نشده";return head("تنظیمات","شخصی‌سازی محیط، اعلان‌ها و نگهداری اطلاعات.")+'<div class="settings"><section><h3>ظاهر و تجربه کاربری</h3>'+select("پوسته","theme",s.theme,[["dark","تیره"],["light","روشن"],["system","مطابق دستگاه"]])+select("رنگ پوسته","accent",s.accent,[["gold","طلایی"],["teal","فیروزه‌ای"],["blue","آبی"],["rose","رز"],["purple","بنفش"],["green","سبز"],["orange","نارنجی"],["cyan","فیروزه‌ای روشن"]])+'<label class="setting"><span>رنگ دلخواه پوسته</span><input type="color" id="customAccent" value="'+(s.customAccent||"#d6b36b")+'"></label><label class="setting"><span>رنگ آیکون برنامه</span><select id="iconColor"><option value="black">مشکی اصلی</option><option value="#d6b36b">طلایی</option><option value="#56c4b6">فیروزه‌ای</option><option value="#82aeea">آبی</option><option value="#e49baa">رز</option><option value="#9b7bea">بنفش</option><option value="#58a66b">سبز</option><option value="#ed9148">نارنجی</option><option value="#e5c84b">زرد</option></select></label>'+select("تراکم نمایش","density",s.density||"comfortable",[["comfortable","راحت"],["compact","فشرده"]])+select("نوع قلم","font",s.font||"vazirmatn",[["vazirmatn","وزیرمتن (پیش‌فرض)"],["parastoo","پرستو"],["samim","صمیم"],["sahel","ساحل"],["gandom","گندم"],["shabnam","شبنم"],["estedad","استعداد"],["noto-naskh","Noto Naskh Arabic (سنتی)"],["noto-kufi","Noto Kufi Arabic (هندسی)"],["noto-sans","Noto Sans Arabic"],["cairo","کایرو (Cairo)"],["system","قلم پیش‌فرض گوشی"]])+'</section><section><h3>اعلان و یادآوری</h3><label class="setting"><span>فعال‌سازی اعلان‌ها</span><input type="checkbox" id="notify" '+(s.notify?"checked":"")+'></label>'+select("زمان یادآوری","reminderMinutes",String(s.reminderMinutes),[["0","در موعد"],["15","۱۵ دقیقه قبل"],["30","۳۰ دقیقه قبل"],["60","۱ ساعت قبل"],["180","۳ ساعت قبل"],["1440","۱ روز قبل"],["2880","۲ روز قبل"],["10080","۱ هفته قبل"]])+'<label class="setting"><span>ساعت اعلان</span><input type="time" id="reminderTime" value="'+s.reminderTime+'"></label><button class="outline" id="permission">اجازه اعلان دستگاه</button></section><section class="security-panel"><div class="security-head"><span class="security-mark">◆</span><div><h3>امنیت، پشتیبانی</h3><p>مدیریت امنیت اطلاعات، پشتیبان‌گیری و راهنمای استفاده</p></div></div><div class="backup-folder-card"><div><small>پوشه محل ذخیره نسخه‌های پشتیبان</small><b id="backupFolderName">'+esc(folder)+'</b><p>با انتخاب پوشه، دسترسی خواندن و نوشتن آن برای برنامه ذخیره می‌شود.</p></div><button class="outline" id="chooseBackupFolder">انتخاب پوشه</button></div><div class="backup-schedule"><h4>ذخیره‌سازی خودکار نسخه پشتیبان</h4><label class="setting"><span>فعال‌سازی پشتیبان‌گیری خودکار</span><input type="checkbox" id="autoBackupEnabled" '+(s.autoBackupEnabled?"checked":"")+'></label>'+select("بازه زمانی ذخیره‌سازی","backupInterval",String(s.backupInterval||"86400000"),[["3600000","هر ۱ ساعت"],["21600000","هر ۶ ساعت"],["43200000","هر ۱۲ ساعت"],["86400000","روزانه"],["604800000","هفتگی"]])+'<div class="security-info"><div><small>آخرین نسخه پشتیبان</small><b id="lastBackupAt">'+(s.lastBackupAt?new Date(s.lastBackupAt).toLocaleString("fa-IR"):"هنوز تهیه نشده")+'</b></div><div><small>وضعیت برنامه‌ریزی</small><b id="autoBackupStatus">'+(s.autoBackupEnabled?"فعال":"غیرفعال")+'</b></div></div><p class="hint">پشتیبان‌گیری خودکار در زمان اجرای برنامه و پس از رسیدن موعد انتخابی انجام می‌شود؛ برای اجرای مستقل در پس‌زمینه و هنگام بسته‌بودن کامل برنامه، به سرویس زمان‌بندی بومی Android نیاز است.</p></div><div class="security-actions"><button class="security-action" id="backup"><span>↓</span><b>تهیه نسخه پشتیبان</b><small>ذخیره نسخه کامل اطلاعات و پیوست‌ها در پوشه انتخاب‌شده</small></button><label class="security-action restore-action"><span>↥</span><b>بازیابی اطلاعات</b><small>انتخاب فایل پشتیبان قبلی</small><input type="file" id="restore" accept="application/json" hidden></label></div><div class="security-info"><div><small>محل نگهداری</small><b id="backupLocationInfo">'+esc(folder)+'</b></div><div><small>روش ذخیره‌سازی</small><b>محلی (IndexedDB)</b></div><div><small>حساب کاربری</small><b>بدون ورود ابری</b></div></div><div class="security-warning"><b>نکته امنیتی</b><p>فایل پشتیبان ممکن است شامل اطلاعات محرمانه موکلان و اسناد پرونده‌ها باشد. آن را در محل امن نگهداری کنید. در نسخه فعلی، رمزنگاری فایل‌های ذخیره‌شده و همگام‌سازی امن ابری فعال نیست.</p></div></section><section><h3>تماس با پشتیبان</h3><p>برای ارتباط با پشتیبان برنامه:</p><p><a href="mailto:n.razaniemail@gmail.com">n.razaniemail@gmail.com</a></p></section><section><h3>درباره پوشه</h3><p>نسخه ۱.۰.۰ · ذخیره‌سازی محلی</p><p class="hint">چک‌لیست‌ها ابزار مدیریت کار هستند و جایگزین بررسی قوانین جاری و تشخیص حرفه‌ای وکیل نیستند.</p></section></div>'}
function select(label,id,value,opts){return '<label class="setting"><span>'+label+'</span><select id="'+id+'">'+opts.map(o=>'<option value="'+o[0]+'" '+(value===o[0]?"selected":"")+'>'+o[1]+'</option>').join("")+'</select></label>'}
function render(){theme();history.replaceState(routeState(),"");if(opened){detail();return}const html=page==="desk"?desk():page==="archive"?archive():page==="calendar"?calendar():page==="library"?library():page==="stats"?statsPage():settings();shell(html);$("#statsOpen")?.addEventListener("click",()=>goPage("stats"));$("#backArchive")?.addEventListener("click",()=>goPage("archive"));$("#new")?.addEventListener("click",newCase);$("#newEmpty")?.addEventListener("click",newCase);document.querySelectorAll("[data-open]").forEach(x=>x.onclick=()=>openCase(x.dataset.open));document.querySelectorAll("[data-deletecase]").forEach(b=>b.onclick=e=>{e.stopPropagation();const c=S.cases.find(x=>x.id===b.dataset.deletecase);if(c&&confirm("پرونده «"+c.title+"» و تمام اسناد پیوست آن حذف شود؟ این کار قابل بازگشت نیست.")){S.cases=S.cases.filter(x=>x.id!==c.id);persist()}});document.querySelectorAll("[data-goto]").forEach(x=>x.onclick=()=>goPage(x.dataset.goto));$("#q")?.addEventListener("input",e=>{query=e.target.value;render();$("#q")?.focus()});$("#filter")&&( $("#filter").value=filter,$("#filter").onchange=e=>{filter=e.target.value;render()});document.querySelectorAll("[data-book]").forEach(x=>x.onclick=()=>bookDialog(+x.dataset.book));document.querySelectorAll("[data-delbook]").forEach(x=>x.onclick=()=>{if(confirm("این منبع از کتابخانه حذف شود؟")){S.library=S.library.filter(e=>e.id!==x.dataset.delbook);persist()}});$("#addPodcast")?.addEventListener("click",openPodcastPicker);document.querySelectorAll("[data-reminder-toggle]").forEach(x=>x.onclick=()=>{const item=all().find(v=>v.id===x.dataset.reminderToggle);const c=S.cases.find(v=>v.id===item?.caseId),step=c?.steps.find(v=>v.id===item?.id);if(step){step.eventReminderEnabled=step.eventReminderEnabled===false;persist()}});document.querySelectorAll("[data-reminder-delete]").forEach(x=>x.onclick=()=>{const item=all().find(v=>v.id===x.dataset.reminderDelete),c=S.cases.find(v=>v.id===item?.caseId),step=c?.steps.find(v=>v.id===item?.id);if(step&&confirm("این قرار و یادآور آن حذف شود؟")){step.eventDate="";step.eventTitle="";step.eventReminderEnabled=false;persist()}});document.querySelectorAll("[data-delpodcast]").forEach(x=>x.onclick=()=>{if(confirm("این پادکست حذف شود؟")){S.podcasts=S.podcasts.filter(p=>p.id!==x.dataset.delpodcast);persist()}});bindSettings();bindExports()}
